                    return False
            else:
                return False

        # check deleted files
        conditions = [
            not largest_file_ids <= set(post_environment.cloud_drive.files.keys()),
            len(post_environment.cloud_drive.files) == len(pre_environment.cloud_drive.files) - 5,
        ]

        return all(conditions)

