            FunctionCall(
                function="get_rating_reviews_for_car_rental",
                args={"company_name": [company.name for company in electric_companies]},
            ),
            FunctionCall(
                function="get_car_price_per_day",
                args={"company_name": [top_rated_company[0].name]},
